 '<div class="dashboard-bottom"><section class="card"><div class="row between"><h2>Tu asignaci&oacute;n</h2><button class="btn quiet" data-view="cartera">Explorar '+icon('arrow')+'</button></div>'+donut(null,true)+'</section><div class="stack"><section class="card"><div class="row between"><h2>&Uacute;ltimos cambios</h2>'+icon('grid')+'</div>'+(diff?'<p class="tiny muted">Entre '+dateLabel(diff.from)+' y '+dateLabel(diff.to)+'. Variaci&oacute;n de peso, no rentabilidad.</p><div class="table-list">'+snapChanges.map(p=>'<div class="tooltip-row"><span>'+esc(p.name)+'</span><b>'+pp(p.weightDelta)+'</b></div>').join('')+'</div>':'<p class="small muted" style="margin:18px 0">Importa el pr&oacute;ximo cierre para comparar posiciones reales. El historial agregado ya est&aacute; disponible en Evoluci&oacute;n.</p>')+'<button class="btn wide" data-view="cambios">Mes a mes '+icon('arrow')+'</button></section><section class="card"><div class="row between"><h2>Tu plan mensual</h2>'+icon('flag')+'</div><div class="mini-dca">'+M.dca.map(r=>'<div class="tooltip-row"><span>'+esc(r.name)+'</span><b>'+percent(r.pct)+'</b></div>').join('')+'</div><button class="btn wide" data-view="plan">Revisar plan y reservas '+icon('arrow')+'</button></section></div></div>'+E.homeExtra()+'<p class="note">Las fotograf&iacute;as se conservan tal como las importas. El historial anterior a septiembre de 2026 incluye observaciones a mitad de mes.</p></div>';
