 ss=ss.filter(p=>stockFilter==='all'||(stockFilter==='positive'?X.stockFacts(data,p).gain>=0:X.stockFacts(data,p).gain<0));
 ss.sort((a,b)=>stockSort==='name'?a.name.localeCompare(b.name):stockSort==='return'?(b.returnSinceEntry??-Infinity)-(a.returnSinceEntry??-Infinity):stockSort==='contribution'?(X.stockFacts(data,b).gain||0)-(X.stockFacts(data,a).gain||0):stockSort==='dividend'?(b.dividends||0)-(a.dividends||0):b.value-a.value);
 return ss.length?ss.map(p=>{const f=X.stockFacts(data,p);return '<button class="stock-card" data-stock="'+esc(p.id)+'"><div class="row">'+logo(p)+'<div class="info"><b>'+esc(p.displayName)+'</b><span>'+esc(p.ticker||'Acci&oacute;n')+'</span></div><div class="stock-return '+signClass(f.returnPct)+'">'+percent(f.returnPct,2,true)+'</div></div><div class="stock-metrics"><div><span class="table-meta">Valor de la foto</span><strong>'+money(p.value)+'</strong></div><div><span class="table-meta">Peso del bloque</span><strong>'+percent(f.weight)+'</strong></div></div><div class="progress"><span style="width:'+f.weight+'%"></span></div><div class="stock-footer"><span>'+percent(f.totalWeight)+' del total</span><span>Aporte: <b>'+pp(f.contribution)+'</b></span></div></button>';}).join(''):'<div class="card empty-text">No hay coincidencias con estos filtros.</div>';
